-- calc_systems_data_quality_score
-- Field: systems.DataQualityScore
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_systems_data_quality_score(p_system_id TEXT)
RETURNS NUMERIC AS $$
